120	/** Names the fields an update actually changed, for `issue.updated`. */
121	export function changedFields<T extends object>(
122	  before: T,
123	  after: T,
124	): readonly string[] {
125	  return Object.keys(after).filter(
126	    (key) =>
127	      JSON.stringify(before[key as keyof T]) !==
128	      JSON.stringify(after[key as keyof T]),
129	  );
130	}
