import { MAX_SUB_ISSUE_DEPTH } from "@/config/constants";

/**
 * Sub-issue tree rules.
 *
 * A root issue sits at level 0 and nothing may sit deeper than
 * `MAX_SUB_ISSUE_DEPTH`. Levels are only ever derived from `parentId` chains,
 * never stored, so these helpers take the numbers the caller measured.
 */

export type IssueHierarchyReason = "cycle" | "too_deep";

/** Raised when a placement would loop the tree or make it too deep. */
export class IssueHierarchyError extends Error {
  readonly code = "conflict" as const;

  constructor(
    readonly issueId: string,
    readonly reason: IssueHierarchyReason,
  ) {
    super(
      reason === "cycle"
        ? `Issue ${issueId} cannot be placed under itself or one of its sub-issues.`
        : `Placing issue ${issueId} there would nest sub-issues deeper than level ${MAX_SUB_ISSUE_DEPTH}.`,
    );
    this.name = "IssueHierarchyError";
  }
}

/**
 * Throws `too_deep` unless the deepest issue of the subtree would still sit at
 * or above `MAX_SUB_ISSUE_DEPTH`.
 *
 * @param parentLevel level of the new parent, or -1 for a root placement
 * @param subtreeHeight levels between the moved issue and its deepest descendant (0 when it has none)
 */
export function assertWithinMaxDepth(
  issueId: string,
  parentLevel: number,
  subtreeHeight: number,
): void {
  const deepestLevel = parentLevel + 1 + subtreeHeight;
  if (deepestLevel > MAX_SUB_ISSUE_DEPTH) {
    throw new IssueHierarchyError(issueId, "too_deep");
  }
}
