/** What the tree walks may run against: the connection or a transaction. */
type Reader = Pick<ReturnType<typeof getDb>, "select">;

/**
 * Every issue below `issueId`, archived or not, level by level. Each issue is
 * visited once, so rows that loop back on themselves cannot trap the walk.
 */
function collectDescendants(
  db: Reader,
  orgId: OrgId,
  issueId: IssueId,
): IssueDescendant[] {
  const seen = new Set<string>([issueId]);
  const found: IssueDescendant[] = [];
  let frontier: readonly string[] = [issueId];

  for (let depth = 1; frontier.length > 0; depth += 1) {
    const next: string[] = [];
    for (const ids of chunked(frontier)) {
      const rows = db
        .select({
          id: issues.id,
          status: issues.status,
          archivedAt: issues.archivedAt,
