        if (seen.has(row.id)) continue;
        seen.add(row.id);
        next.push(row.id);
        found.push({
          id: row.id as IssueId,
          status: row.status,
          archivedAt: brandStampOrNull(row.archivedAt),
          depth,
        });
      }
    }
    frontier = next;
  }

  return found;
}

