export async function listAncestorIds(
  orgId: OrgId,
  issueId: IssueId,
): Promise<readonly IssueId[]> {
  const db = getDb();
  const seen = new Set<string>([issueId]);
  const chain: IssueId[] = [];
  let current: string = issueId;

  for (;;) {
    const row = db
      .select({ parentId: issues.parentId })
      .from(issues)
      .where(and(orgPredicate(issues.orgId, orgId), eq(issues.id, current)))
      .get();
    if (!row || row.parentId === null || seen.has(row.parentId)) break;

    seen.add(row.parentId);
    chain.push(row.parentId as IssueId);
    current = row.parentId;
  }

  return chain;
}

