  for (let at = 0; at < items.length; at += ID_CHUNK_SIZE) {
    chunks.push(items.slice(at, at + ID_CHUNK_SIZE));
  }
  return chunks;
}

/** What the tree walks may run against: the connection or a transaction. */
type Reader = Pick<ReturnType<typeof getDb>, "select">;

/**
 * Every issue below `issueId`, archived or not, level by level. Each issue is
 * visited once, so rows that loop back on themselves cannot trap the walk.
 */
function collectDescendants(
  db: Reader,
  orgId: OrgId,
  issueId: IssueId,
): IssueDescendant[] {
  const seen = new Set<string>([issueId]);
  const found: IssueDescendant[] = [];
  let frontier: readonly string[] = [issueId];

  for (let depth = 1; frontier.length > 0; depth += 1) {
    const next: string[] = [];
    for (const ids of chunked(frontier)) {
      const rows = db
        .select({
          id: issues.id,
          status: issues.status,
          archivedAt: issues.archivedAt,
        })
        .from(issues)
        .where(
          and(orgPredicate(issues.orgId, orgId), inArray(issues.parentId, [...ids])),
        )
        .all();

      for (const row of rows) {
        if (seen.has(row.id)) continue;
        seen.add(row.id);
        next.push(row.id);
        found.push({
          id: row.id as IssueId,
          status: row.status,
          archivedAt: brandStampOrNull(row.archivedAt),
          depth,
        });
      }
    }
    frontier = next;
  }

  return found;
}

/** Every issue below `issueId` at any depth, archived ones included. */
export async function listDescendants(
  orgId: OrgId,
  issueId: IssueId,
): Promise<readonly IssueDescendant[]> {
  return collectDescendants(getDb(), orgId, issueId);
}

/**
 * The parents above `issueId`, nearest first, stopping at the root (or where
 * the chain would revisit an issue).
 */
export async function listAncestorIds(
  orgId: OrgId,
  issueId: IssueId,
): Promise<readonly IssueId[]> {
  const db = getDb();
  const seen = new Set<string>([issueId]);
  const chain: IssueId[] = [];
  let current: string = issueId;

  for (;;) {
    const row = db
      .select({ parentId: issues.parentId })
      .from(issues)
      .where(and(orgPredicate(issues.orgId, orgId), eq(issues.id, current)))
      .get();
    if (!row || row.parentId === null || seen.has(row.parentId)) break;

    seen.add(row.parentId);
    chain.push(row.parentId as IssueId);
    current = row.parentId;
  }

  return chain;
}

/** Direct sub-issues that are not archived, oldest first. */
export async function listSubIssues(
  orgId: OrgId,
  parentId: IssueId,
): Promise<readonly Issue[]> {
  const rows = getDb()
    .select()
    .from(issues)
    .where(
      and(
        ...compact(
          orgPredicate(issues.orgId, orgId),
          eq(issues.parentId, parentId),
          livePredicate(issues.archivedAt, {}),
        ),
      ),
    )
    .orderBy(asc(issues.createdAt), asc(issues.number))
    .all();

  const labels = await listLabelsForIssues(
    orgId,
    rows.map((row) => row.id as IssueId),
  );
  return rows.map((row) =>
    toIssue(row, (labels[row.id] ?? []).map((label) => label.id)),
  );
}

/** Open/closed counts over the live issues below `issueId`, at any depth. */
export async function getIssueRollup(
  orgId: OrgId,
  issueId: IssueId,
): Promise<IssueRollup> {
  let open = 0;
  let closed = 0;
  for (const below of collectDescendants(getDb(), orgId, issueId)) {
    if (below.archivedAt !== null) continue;
    if (CLOSED_ISSUE_STATUSES.includes(below.status)) closed += 1;
    else open += 1;
  }
  return { total: open + closed, open, closed };
}

export async function setIssueParent(
  orgId: OrgId,
  issueId: IssueId,
  parentId: IssueId | null,
): Promise<Issue> {
  const row = getDb()
    .update(issues)
    .set({ parentId, updatedAt: toIsoTimestamp(new Date()) })
    .where(and(orgPredicate(issues.orgId, orgId), eq(issues.id, issueId)))
    .returning()
    .get();

  if (!row) throw new Error(`Issue ${issueId} not found`);

  const labels = await listLabelsForIssues(orgId, [issueId]);
  return toIssue(row, (labels[issueId] ?? []).map((label) => label.id));
}

/**
 * Archives an issue together with every live issue below it, in one
 * transaction and under one timestamp. Issues that were already archived are
 * left exactly as they were. `cascaded` lists what went down with the issue.
 */
export async function archiveIssueWithDescendants(
  orgId: OrgId,
  issueId: IssueId,
): Promise<{ readonly issue: Issue; readonly cascaded: readonly Issue[] }> {
  const patch = archivePatch();

  return getDb().transaction((tx) => {
    const liveBelow = collectDescendants(tx, orgId, issueId)
      .filter((below) => below.archivedAt === null)
      .map((below) => below.id);

    const row = tx
      .update(issues)
      .set(patch)
      .where(and(orgPredicate(issues.orgId, orgId), eq(issues.id, issueId)))
      .returning()
      .get();
    if (!row) throw new Error(`Issue ${issueId} not found`);

    const cascaded = chunked(liveBelow).flatMap((ids) =>
      tx
        .update(issues)
        .set(patch)
        .where(
          and(
            ...compact(
              orgPredicate(issues.orgId, orgId),
              inArray(issues.id, [...ids]),
              livePredicate(issues.archivedAt, {}),
            ),
          ),
        )
        .returning()
        .all(),
    );

    return { issue: toIssue(row), cascaded: cascaded.map((r) => toIssue(r)) };
  });
}

