describe("sub_issues_completed", () => {
  it("tells the parent's assignee once, when the last open sub-issue closes", async () => {
    const parent = await make({ assigneeId: tenant.userIds.admin });
    const a = await make({ parentId: parent.id });
    const b = await make({ parentId: parent.id });
    const before = await completionNotices(tenant.userIds.admin);

    await close(a);
    expect(await completionNotices(tenant.userIds.admin)).toBe(before);

    await close(b, tenant.actors.member, "canceled");
    expect(await completionNotices(tenant.userIds.admin)).toBe(before + 1);

    // Closed to another closed status: not a closing.
    await close(b, tenant.actors.member, "done");
    expect(await completionNotices(tenant.userIds.admin)).toBe(before + 1);

    // Reopening and closing again tells again.
    await close(b, tenant.actors.member, "todo");
    await close(b);
    expect(await completionNotices(tenant.userIds.admin)).toBe(before + 2);
  });

  it("looks at open issues at any depth below the parent", async () => {
    const parent = await make({ assigneeId: tenant.userIds.admin });
