    const before = await completionNotices(tenant.userIds.admin);

    await close(child);
    expect(await completionNotices(tenant.userIds.admin)).toBe(before);

    // Only the direct parent is considered: the child is closed too, but its
    // own assignee gets the notice, not the grandparent.
    await close(grandchild);
    expect(await completionNotices(tenant.userIds.admin)).toBe(before);
  });

