    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, archivedParent.id);

    expect(await completionNotices(tenant.userIds.member)).toBe(before.member);
    expect(await completionNotices(tenant.userIds.admin)).toBe(before.admin + 1);
