/**
 * Sub-issues: placing, moving and listing them, the roll-up, the archive
 * cascade and the "all sub-issues closed" notice.
 */
import { afterAll, afterEach, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import { MAX_SUB_ISSUE_DEPTH } from "@/config/constants";
import { subscribe } from "@/lib/event-bus";
import { IssueHierarchyError } from "@/lib/issue-hierarchy";
import { PermissionDeniedError } from "@/lib/permissions";
import { AlreadyArchivedError } from "@/lib/soft-delete";
import { TenantScopeError } from "@/lib/tenant";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as issueService from "@/server/services/issue-service";
import { listNotifications } from "@/server/services/notification-service";
import { NotFoundError } from "@/server/services/_support";
import {
  createTenant,
  issueInput,
  useTemporaryDatabase,
} from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { Actor } from "@/types/member";
import type { IssueId, UserId } from "@/types/common";
import type { Issue, IssueStatus } from "@/types/issue";
import type { TaskflowEventMap, TaskflowEventType, Unsubscribe } from "@/types/event";

let cleanup: () => void;
let tenant: Tenant;
let other: Tenant;
const detachers: Unsubscribe[] = [];

function capture<K extends TaskflowEventType>(type: K): TaskflowEventMap[K][] {
  const seen: TaskflowEventMap[K][] = [];
  detachers.push(
    subscribe(type, (payload) => {
      seen.push(payload);
    }),
  );
  return seen;
}

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  tenant = await createTenant("subissues");
  other = await createTenant("subother");
});

afterEach(() => {
  while (detachers.length > 0) detachers.pop()?.();
});

afterAll(() => {
  cleanup();
});

let counter = 0;

async function make(
  extra: {
    parentId?: IssueId | null;
    status?: IssueStatus;
    assigneeId?: UserId | null;
    title?: string;
  } = {},
  t: Tenant = tenant,
  actor: Actor = t.actors.member,
): Promise<Issue> {
  counter += 1;
  return issueService.createIssue(actor, {
    ...issueInput(t.org.id, t.project.id, {
      title: extra.title ?? `Sub-issue subject ${counter}`,
      assigneeId: extra.assigneeId ?? null,
    }),
    parentId: extra.parentId ?? null,
    status: extra.status ?? "todo",
  });
}

function setParent(issue: Issue, parentId: IssueId | null, actor: Actor = tenant.actors.member) {
  return issueService.setIssueParent(actor, {
    orgId: issue.orgId,
    issueId: issue.id,
    parentId,
  });
}

async function completionNotices(userId: UserId): Promise<number> {
  const page = await listNotifications(tenant.actors.owner, {
    orgId: tenant.org.id,
    recipientId: userId,
    unreadOnly: false,
    kind: ["sub_issues_completed"],
    limit: 100,
    cursor: null,
  });
  return page.items.length;
}

function close(issue: Issue, actor: Actor = tenant.actors.member, status: IssueStatus = "done") {
  return issueService.changeIssueStatus(actor, {
    orgId: issue.orgId,
    issueId: issue.id,
    status,
  });
}

describe("setIssueParent", () => {
  it("places, moves and removes a parent, announcing each as issue.updated", async () => {
    const first = await make();
    const second = await make();
    const child = await make();
    const updates = capture("issue.updated");

    const placed = await setParent(child, first.id);
    expect(placed.parentId).toBe(first.id);
    const moved = await setParent(child, second.id);
    expect(moved.parentId).toBe(second.id);
    const root = await setParent(child, null);
    expect(root.parentId).toBeNull();

    expect(updates.map((u) => [u.issueId, u.changedFields])).toEqual([
      [child.id, ["parentId"]],
      [child.id, ["parentId"]],
      [child.id, ["parentId"]],
    ]);
    expect((await issueRepo.findIssueById(tenant.org.id, child.id))?.parentId).toBeNull();
  });

  it("changes and announces nothing when the parent stays the same", async () => {
    const parent = await make();
    const child = await make({ parentId: parent.id });
    const updates = capture("issue.updated");

    const again = await setParent(child, parent.id);

    expect(again.parentId).toBe(parent.id);
    expect(updates).toHaveLength(0);
  });

  it("moves the sub-issues along with the issue", async () => {
    const newParent = await make();
    const middle = await make();
    const leaf = await make({ parentId: middle.id });

    await setParent(middle, newParent.id);

    expect((await issueRepo.findIssueById(tenant.org.id, leaf.id))?.parentId).toBe(middle.id);
    const rollup = await issueService.getIssueRollup(tenant.actors.member, tenant.org.id, newParent.id);
    expect(rollup.total).toBe(2);
  });

  it("refuses an orgId outside the actor's workspace", async () => {
    const issue = await make();
    await expect(
      issueService.setIssueParent(tenant.actors.member, {
        orgId: other.org.id,
        issueId: issue.id,
        parentId: null,
      }),
    ).rejects.toBeInstanceOf(TenantScopeError);
  });

  it("treats an unknown issue, another workspace's issue and a foreign parent as not found", async () => {
    const issue = await make();
    const foreign = await make({}, other);
    const elsewhere = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, (await projectInTenant()).id, { title: "Other project issue" }),
    );

    await expect(setParent(foreign, null)).rejects.toBeInstanceOf(NotFoundError);
    await expect(setParent(issue, foreign.id)).rejects.toBeInstanceOf(NotFoundError);
    await expect(setParent(issue, elsewhere.id)).rejects.toBeInstanceOf(NotFoundError);
    expect((await issueRepo.findIssueById(tenant.org.id, issue.id))?.parentId).toBeNull();
  });

  it("requires issue:update, with the ownership escalation for one's own issue", async () => {
    const parent = await make();
    const theirs = await make({}, tenant, tenant.actors.admin);
    const mine = await make({}, tenant, tenant.actors.viewer).catch(() => null);

    await expect(setParent(theirs, parent.id, tenant.actors.viewer)).rejects.toBeInstanceOf(
      PermissionDeniedError,
    );
    // A viewer cannot create issues, so the escalation is shown through an assignee instead.
    expect(mine).toBeNull();
    const assigned = await make({ assigneeId: tenant.userIds.viewer });
    const placed = await setParent(assigned, parent.id, tenant.actors.viewer);
    expect(placed.parentId).toBe(parent.id);
  });

  it("refuses to move an archived issue and to adopt under an archived parent", async () => {
    const live = await make();
    const parent = await make();
    const gone = await make();
    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, gone.id);
    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, parent.id);

    await expect(setParent(gone, null)).rejects.toBeInstanceOf(AlreadyArchivedError);
    await expect(setParent(live, parent.id)).rejects.toBeInstanceOf(AlreadyArchivedError);
  });

  it("refuses a cycle: under itself or under anything below it", async () => {
    const top = await make();
    const middle = await make({ parentId: top.id });
    const leaf = await make({ parentId: middle.id });
    const updates = capture("issue.updated");

    for (const target of [top.id, middle.id, leaf.id]) {
      await expect(setParent(top, target)).rejects.toMatchObject({
        reason: "cycle",
        issueId: top.id,
      });
    }
    await expect(setParent(top, top.id)).rejects.toBeInstanceOf(IssueHierarchyError);
    expect(updates).toHaveLength(0);
    expect((await issueRepo.findIssueById(tenant.org.id, top.id))?.parentId).toBeNull();
  });

  it("judges a move by where the deepest descendant would land", async () => {
    expect(MAX_SUB_ISSUE_DEPTH).toBe(3);
    // chain: level 0..3
    const l0 = await make();
    const l1 = await make({ parentId: l0.id });
    const l2 = await make({ parentId: l1.id });
    const l3 = await make({ parentId: l2.id });

    // Nothing may be created below the deepest level.
    await expect(make({ parentId: l3.id })).rejects.toMatchObject({ reason: "too_deep" });

    // A lone issue fits under l2 (level 3) but not under l3.
    const lone = await make();
    await expect(setParent(lone, l3.id)).rejects.toMatchObject({ reason: "too_deep" });
    expect((await setParent(lone, l2.id)).parentId).toBe(l2.id);

    // An issue with one sub-issue lands its child one level deeper.
    const pair = await make();
    await make({ parentId: pair.id });
    await expect(setParent(pair, l2.id)).rejects.toMatchObject({ reason: "too_deep" });
    expect((await setParent(pair, l1.id)).parentId).toBe(l1.id);

    // The refused move changed nothing.
    expect((await issueRepo.findIssueById(tenant.org.id, pair.id))?.parentId).toBe(l1.id);
  });

  it("creates nothing and announces nothing when the parent is refused", async () => {
    const archivedParent = await make();
    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, archivedParent.id);
    const foreign = await make({}, other);
    const created = capture("issue.created");
    const before = await issueRepo.countIssues(tenant.org.id, tenant.project.id, {
      includeArchived: true,
    });

    await expect(make({ parentId: archivedParent.id })).rejects.toBeInstanceOf(AlreadyArchivedError);
    await expect(make({ parentId: foreign.id })).rejects.toBeInstanceOf(NotFoundError);

    expect(created).toHaveLength(0);
    await expect(
      issueRepo.countIssues(tenant.org.id, tenant.project.id, { includeArchived: true }),
    ).resolves.toBe(before);
  });
});

describe("listSubIssues and getIssueRollup", () => {
  it("lists direct, live sub-issues oldest first", async () => {
    const parent = await make();
    const a = await make({ parentId: parent.id });
    const b = await make({ parentId: parent.id });
    const c = await make({ parentId: parent.id });
    await make({ parentId: a.id });
    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, b.id);

    const listed = await issueService.listSubIssues(tenant.actors.viewer, tenant.org.id, parent.id);
    expect(listed.map((i) => i.id)).toEqual([a.id, c.id]);
  });

  it("guards listing and the roll-up like reads", async () => {
    const parent = await make();
    const foreign = await make({}, other);

    await expect(
      issueService.listSubIssues(tenant.actors.member, other.org.id, parent.id),
    ).rejects.toBeInstanceOf(TenantScopeError);
    await expect(
      issueService.getIssueRollup(tenant.actors.member, other.org.id, parent.id),
    ).rejects.toBeInstanceOf(TenantScopeError);
    await expect(
      issueService.listSubIssues(tenant.actors.member, tenant.org.id, foreign.id),
    ).rejects.toBeInstanceOf(NotFoundError);
    await expect(
      issueService.getIssueRollup(tenant.actors.member, tenant.org.id, foreign.id),
    ).rejects.toBeInstanceOf(NotFoundError);
  });

  it("rolls up every live issue below at any depth", async () => {
    const root = await make();
    const open = await make({ parentId: root.id, status: "in_progress" });
    const done = await make({ parentId: root.id, status: "done" });
    await make({ parentId: open.id, status: "canceled" });
    await make({ parentId: open.id, status: "backlog" });
    const gone = await make({ parentId: done.id });
    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, gone.id);

    await expect(
      issueService.getIssueRollup(tenant.actors.viewer, tenant.org.id, root.id),
    ).resolves.toEqual({ total: 4, open: 2, closed: 2 });
    await expect(
      issueService.getIssueRollup(tenant.actors.viewer, tenant.org.id, gone.id),
    ).resolves.toEqual({ total: 0, open: 0, closed: 0 });
  });

  it("counts a tree larger than any single page or id list", async () => {
    const root = await make();
    const project = tenant.project.id;
    let number = await issueRepo.nextIssueNumber(tenant.org.id, project);
    const total = 1250;
    for (let i = 0; i < total; i += 1) {
      await issueRepo.insertIssue(
        {
          ...issueInput(tenant.org.id, project, { title: `Bulk child ${i}` }),
          parentId: root.id,
          status: i % 5 === 0 ? "done" : "todo",
        },
        tenant.userIds.member,
        number,
      );
      number += 1;
    }

    await expect(
      issueService.getIssueRollup(tenant.actors.member, tenant.org.id, root.id),
    ).resolves.toEqual({ total, open: 1000, closed: 250 });
    expect(
      (await issueService.listSubIssues(tenant.actors.member, tenant.org.id, root.id)).length,
    ).toBe(total);
  });
});

describe("archiving with sub-issues", () => {
  it("archives every live issue below, each with its own issue.archived", async () => {
    const grandparent = await make();
    const root = await make({ parentId: grandparent.id });
    const child = await make({ parentId: root.id });
    const grandchild = await make({ parentId: child.id });
    const earlier = await make({ parentId: root.id });
